			NativeGroupIteration iteration = new NativeGroupIteration(fixture.source, opaqueInput, fixture.layout,
					new int[] { 0 }, specs, false, EmptyBindingSet.getInstance(), null, null, false, target);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance(), target,
					iteration.cancellation);
