	@Test
	void aggregateOpenEventsSeparatePreviewAndRecordActualResultDemand(@TempDir Path directory) throws Exception {
		Path recordingPath = directory.resolve("native-aggregate-open.jfr");
		long typedEvaluation;
		long typedOwner;
		long fullEvaluation;
		long fullOwner;
		try (Recording recording = new Recording()) {
			recording.enable(AGGREGATE_EVENT).withThreshold(Duration.ZERO);
			recording.start();
			try (Fixture previewFixture = fixture()) {
				SingletonSet target = telemetryTarget();
				AggregateSpec[] specs = lexicalLengthSpecs();
				NativeGroupIteration iteration = iteration(previewFixture, target, specs, null);
				RowState row = new RowState(previewFixture.source, previewFixture.layout, EmptyBindingSet.getInstance(),
						target, iteration.cancellation);
				assertTrue(iteration.initialize(row));
				NativeGroupStep previewStep = step(previewFixture, specs, target, null);
				preview(previewStep, iteration, row, previewFixture.source.executionContext());
				row.closeDecodedInputs();
				iteration.close();
			}
			try (Fixture typedFixture = fixture()) {
				SingletonSet target = telemetryTarget();
				NativeGroupStep typed = step(typedFixture, lexicalLengthSpecs(), target,
						LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
				try (NativeResultCursor cursor = typed.evaluateNative(EmptyBindingSet.getInstance())) {
					typedEvaluation = cursor.cancellation().evaluationId();
					typedOwner = cursor.cancellation().ownerThreadId();
					long groups = 0L;
					NativeResultRow row;
					while ((row = cursor.next()) != null) {
						if (row.cell("group").value().stringValue().equals("100")) {
							assertEquals(4L, row.cell("length").codePointLength());
						}
						groups++;
					}
					assertEquals(100L, groups);
				}
				assertEquals(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP,
						target.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH));
			}
			try (Fixture fullFixture = fixture()) {
				SingletonSet target = telemetryTarget();
				AggregateSpec[] specs = { AggregateSpec.groupConcat("text", 1, false, "|") };
				NativeGroupStep full = step(fullFixture, specs, target,
						LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
				try (NativeResultCursor cursor = full.evaluateNative(EmptyBindingSet.getInstance())) {
					fullEvaluation = cursor.cancellation().evaluationId();
					fullOwner = cursor.cancellation().ownerThreadId();
					long groups = 0L;
					NativeResultRow row;
					while ((row = cursor.next()) != null) {
						if (row.cell("group").value().stringValue().equals("100")) {
							assertEquals(FIRST_GROUP_DUPLICATED, row.cell("text").value().stringValue());
						}
						groups++;
					}
					assertEquals(100L, groups);
				}
				assertEquals(LmdbNativeAttemptMetrics.PATH_SINGLE_SLOT_GROUPS,
						target.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH));
			}
			recording.stop();
			recording.dump(recordingPath);
		}
		List<jdk.jfr.consumer.RecordedEvent> events = RecordingFile.readAllEvents(recordingPath)
				.stream()
				.filter(event -> AGGREGATE_EVENT.equals(event.getEventType().getName()))
				.toList();
		assertEquals(2, events.size(),
				"preview must not publish an aggregate-open event; each selected producer open must publish one");
		Map<Long, jdk.jfr.consumer.RecordedEvent> byEvaluation = new HashMap<>();
		for (jdk.jfr.consumer.RecordedEvent event : events) {
			byEvaluation.put(event.getLong("evaluationId"), event);
			assertEquals(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP, event.getString("strategy"));
		}
		assertEquals("LEXICAL_LENGTH", byEvaluation.get(typedEvaluation).getString("resultDemands"));
		assertEquals(typedOwner, byEvaluation.get(typedEvaluation).getLong("ownerThreadId"));
		assertEquals("FULL_VALUE", byEvaluation.get(fullEvaluation).getString("resultDemands"));
		assertEquals(fullOwner, byEvaluation.get(fullEvaluation).getLong("ownerThreadId"));
	}

	@Test
	void orderedFullGroupingReturnsAnOwnedBoundedReplay() throws Exception {
		try (Fixture fixture = fixture()) {
			AggregateSpec[] specs = { AggregateSpec.star("count") };
			NativeGroupIteration iteration = iteration(fixture, null, specs, null);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance(), (TupleExpr) null,
					iteration.cancellation);
			assertTrue(iteration.initialize(row), "the ordered FULL_VALUE source must be admitted");
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			long baseline = ledger.usedBytes();
			List<BindingSet> results = iteration.evaluateOrderedSinglePatternGroups(row,
					LmdbNativeAttemptMetrics.direct());
			assertNotNull(results);
			assertEquals(100, results.size());
			Map<String, Long> byGroup = new HashMap<>();
			for (BindingSet result : results) {
				byGroup.put(result.getValue("group").stringValue(), ((Literal) result.getValue("count")).longValue());
			}
			assertEquals(3L, byGroup.get("100"));
			assertEquals(2L, byGroup.get("101"));
			try {
				assertAll("ordered FULL outputs remain bounded and query-accounted",
						() -> assertTrue(results instanceof NativeReplayBindingList,
								"ordered FULL results must not retain an unbounded ArrayList of BindingSets"),
						() -> assertTrue(ledger.usedBytes() > baseline,
								"the published ordered result must charge its bounded replay to the query owner"));
			} finally {
				if (results instanceof NativeReplayBindingList replay) {
					replay.close();
				}
			}
			assertEquals(baseline, ledger.usedBytes(), "closing the ordered result releases its replay reservation");
			row.closeDecodedInputs();
			iteration.close();
		}
	}

	@Test
	void parallelGroupTableReturnsAnOwnedBoundedReplay() throws Exception {
		try (Fixture fixture = fixture()) {
			AggregateSpec[] specs = { AggregateSpec.groupConcat("text", 1, false, "|") };
			NativeGroupIteration iteration = new NativeGroupIteration(fixture.source, SlotPlan.empty(), fixture.layout,
					new int[] { 0 }, specs, false, EmptyBindingSet.getInstance(), null, null, false, null);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance(), (TupleExpr) null,
					iteration.cancellation);
			assertTrue(iteration.initialize(row));
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			List<String> ledgerStages = new ArrayList<>();
			ledgerStages.add("beforeIntern=" + ledger.usedBytes());
			Literal firstGroupValue = SimpleValueFactory.getInstance().createLiteral("01", XMLSchema.INT);
			long firstGroup = fixture.source.internComputedValue(firstGroupValue);
			assertEquals(firstGroupValue, fixture.source.lazyValue(firstGroup));
			ledgerStages.add("afterInternFirstGroup=" + ledger.usedBytes());
			Literal secondGroupValue = SimpleValueFactory.getInstance().createLiteral("1", XMLSchema.INTEGER);
			long secondGroup = fixture.source.internComputedValue(secondGroupValue);
			assertEquals(secondGroupValue, fixture.source.lazyValue(secondGroup));
			ledgerStages.add("afterInternSecondGroup=" + ledger.usedBytes());
			Literal emojiLambdaValue = SimpleValueFactory.getInstance().createLiteral("\ud83d\ude00\u03bb");
			long emojiLambda = fixture.source.internComputedValue(emojiLambdaValue);
			assertEquals(emojiLambdaValue, fixture.source.lazyValue(emojiLambda));
			ledgerStages.add("afterInternEmojiPayload=" + ledger.usedBytes());
			Literal xValue = SimpleValueFactory.getInstance().createLiteral("x");
			long x = fixture.source.internComputedValue(xValue);
			assertEquals(xValue, fixture.source.lazyValue(x));
			ledgerStages.add("afterInternXPayload=" + ledger.usedBytes());
			assertNotEquals(firstGroup, secondGroup, "fixture group terms must have distinct mapped IDs");
			assertNotEquals(emojiLambda, x, "fixture payload terms must have distinct mapped IDs");
			long baseline = ledger.usedBytes();
			ledgerStages.add("postInternBaseline=" + baseline);
			List<BindingSet> results;
			long afterTableRender;
			try (NativeGroupTable table = NativeGroupTable.createParallel(new int[] { 0 }, specs,
					iteration.aggContext, AggregateDistinctChannels.allHash(specs))) {
				add(table, row, firstGroup, emojiLambda);
				add(table, row, firstGroup, emojiLambda);
				add(table, row, firstGroup, x);
				add(table, row, secondGroup, x);
				results = table.results(iteration, LmdbNativeAttemptMetrics.direct());
				afterTableRender = ledger.usedBytes();
			}
			long afterTableClose = ledger.usedBytes();
			ledgerStages.add("afterTableRender=" + afterTableRender);
			ledgerStages.add("afterTableClose=" + afterTableClose);
			long afterAggregateContextClose;
			long afterReplayClose;
			long afterSourceClose;
			Map<Value, String> byGroup = new HashMap<>();
			Set<Value> resultGroups;
			try {
				iteration.aggContext.close();
				afterAggregateContextClose = ledger.usedBytes();
				ledgerStages.add("afterAggContextClose=" + afterAggregateContextClose);
				for (BindingSet result : results) {
					byGroup.put(result.getValue("group"), result.getValue("text").stringValue());
				}
				resultGroups = results.stream()
						.map(binding -> binding.getValue("group"))
						.collect(java.util.stream.Collectors.toSet());
			} finally {
				if (results instanceof NativeReplayBindingList replay) {
					replay.close();
				}
				afterReplayClose = ledger.usedBytes();
				ledgerStages.add("afterReplayClose=" + afterReplayClose);
				row.closeDecodedInputs();
				iteration.close();
				fixture.source.executionContext().close();
				afterSourceClose = ledger.usedBytes();
				ledgerStages.add("afterSourceClose=" + afterSourceClose);
			}
			assertAll("parallel table outputs remain bounded and query-accounted; " + ledgerStages,
					() -> assertEquals(2, results.size()),
					() -> assertEquals(FIRST_GROUP_DUPLICATED, byGroup.get(firstGroupValue)),
					() -> assertEquals("x", byGroup.get(secondGroupValue)),
					() -> assertEquals(Set.of(firstGroupValue, secondGroupValue), resultGroups,
							"generated noncanonical RDF-term IDs must retain exact group-key identity"),
					() -> assertTrue(results instanceof NativeReplayBindingList,
							"parallel table rendering must not retain unbounded output BindingSets"),
					() -> assertTrue(afterAggregateContextClose > baseline,
							"the live result replay must retain positive query-ledger ownership"),
					() -> assertEquals(baseline, afterReplayClose,
							"closing the table result releases its replay reservation"),
					() -> assertEquals(0L, afterSourceClose,
							"closing the source context releases interned generated payloads"));
		}
	}

	@Test
	void alreadyGroupedFullConcatStreamsAndClosesItsSpilledSegments() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		String previousGroupLimit = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
		Path temporaryDirectory = Path.of(System.getProperty("java.io.tmpdir"));
		Set<String> existingConcatSpills = temporaryFiles(temporaryDirectory, "rdf4j-lmdb-concat-").stream()
				.map(path -> path.getFileName().toString())
				.collect(java.util.stream.Collectors.toSet());
		AtomicReference<List<Path>> concatSpillsObserved = new AtomicReference<>(List.of());
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		try (Fixture fixture = orderedConcatFixture(2, 64, true, temporaryDirectory, existingConcatSpills,
				concatSpillsObserved)) {
			AggregateSpec[] specs = { AggregateSpec.groupConcat("text", 1, true, "🧩") };
			NativeGroupIteration iteration = iteration(fixture, null, specs, null);
			RowState admitted = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
			try {
				assertTrue(iteration.initialize(admitted),
						"the exact source must be admitted before checking its order");
				assertTrue(specs[0].reducer.requiresEncounterReplay,
						"FULL GROUP_CONCAT observes input encounter order");
				NativeTupleDistinctPlan groupOrder = LmdbNativeOrderPlanner.tuple(iteration.arg, iteration.groupSlots,
						admitted);
				assertEquals(NativeDistinctStrategy.ADJACENT, groupOrder.strategy,
						"the admitted S-order proves contiguous groups independently of aggregate DISTINCT channels");
				assertArrayEquals(iteration.groupSlots, groupOrder.partitionSlots,
						"the input-order proof covers the complete grouping key");
				NativeGroupResultCursor.GroupingPlan plan = NativeGroupResultCursor.orderedPlan(iteration, admitted);
				assertNotNull(plan,
						"a producer already in encounter order may stream FULL GROUP_CONCAT without reordering its input");
				assertTrue(plan.streaming(), "the proven prefix is consumed as a stream");

				List<String> segments = new ArrayList<>(64);
				for (int index = 0; index < 64; index++) {
					segments.add("λ🧭e\u0301-" + index);
				}
				String expected = String.join("🧩", segments);
				try (NativeGroupResultCursor cursor = plan.open(iteration, fixture.source.executionContext())) {
					NativeResultRow first = cursor.next();
					assertNotNull(first, "the first complete group is available before the entire input is read");
					assertEquals("100", first.cell("group").value().stringValue());
					assertEquals(NativeResultCell.Kind.RDF_TERM, first.cell("text").kind());
					assertEquals(expected, first.cell("text").value().stringValue(),
							"spilled segments retain exact Unicode and encounter-order separators");
					assertEquals(65, fixture.reads.get(),
							"streaming consumes one lookahead row, not all groups, before emitting the first result");
					assertTrue(fixture.reads.get() < 128);
					assertFalse(concatSpillsObserved.get().isEmpty(),
							"64 retained segments cross the bounded concatenation spill threshold");
				}
				assertEquals(1, fixture.closes.get(), "early result close closes the accepted source exactly once");
				assertTrue(concatSpillsObserved.get().stream().noneMatch(Files::exists),
						"closing the streamed group releases its concatenation spill file");
			} finally {
				admitted.closeDecodedInputs();
				iteration.close();
				fixture.source.executionContext().close();
			}
			assertEquals(0L, manager.usedBytes(), "closing the stream releases all per-query aggregate ownership");
			try (Fixture unordered = orderedConcatFixture(2, 64, false, null, Set.of(),
					new AtomicReference<>(List.of()))) {
				AggregateSpec[] unorderedSpecs = { AggregateSpec.groupConcat("text", 1, true, "🧩") };
				NativeGroupIteration unorderedIteration = iteration(unordered, null, unorderedSpecs, null);
				RowState unorderedRow = new RowState(unordered.source, unordered.layout, EmptyBindingSet.getInstance());
				try {
					assertTrue(unorderedIteration.initialize(unorderedRow),
							"the order-changing control is also admitted");
					assertNull(NativeGroupResultCursor.orderedPlan(unorderedIteration, unorderedRow),
							"an input which interleaves group keys cannot use the encounter-order streaming recipe");
				} finally {
					unorderedRow.closeDecodedInputs();
					unorderedIteration.close();
				}
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restoreProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroupLimit);
		}
	}

	private static List<Path> temporaryFiles(Path directory, String prefix) throws IOException {
		try (var paths = Files.list(directory)) {
			return paths.filter(path -> path.getFileName().toString().startsWith(prefix)).toList();
		}
	}

	@Test
	void orderedGroupMapClosesItsSpilledTableAfterInputFailure() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		String previousGroupLimit = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		String previousGroupsEnabled = System.getProperty(NativeCountGroupStore.ENABLED_PROPERTY);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		System.setProperty(NativeCountGroupStore.ENABLED_PROPERTY, "true");
		try (Fixture fixture = fixture()) {
			AggregateSpec[] specs = { AggregateSpec.groupConcat("text", 1, false, "|") };
			IOException inputFailure = new IOException("controlled failure after admitted spill input");
			AtomicInteger cursorCloses = new AtomicInteger();
			SlotPlan input = new RowsThenFailurePlan(0, 1, 200L, 256, inputFailure, cursorCloses);
			NativeGroupIteration iteration = new NativeGroupIteration(fixture.source, input, fixture.layout,
					new int[] { 0 }, specs, false, EmptyBindingSet.getInstance(), null, null, false,
					(TupleExpr) null);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
			try {
				assertTrue(iteration.initialize(row), "the grouping entry row is admitted before source advancement");
				long baseline = manager.usedBytes();
				NativeAggregateDistinctPlan plan = new NativeAggregateDistinctPlan(input, NativeSlotOrder.NONE,
						AggregateDistinctChannels.sequential(specs), new int[0], 0);
				long spillsBefore = NativeSpillSort.SPILL_RUNS.get();
				long deletedRunsBefore = NativeSpillSort.DELETED_RUNS.get();
				long mergedBefore = NativeSpillSort.MERGED_RUNS.get();
				long deletedMergedBefore = NativeSpillSort.DELETED_MERGED_RUNS.get();
				QueryEvaluationException observed = assertThrows(QueryEvaluationException.class,
						() -> iteration.evaluateOrderedGroupMap(row, plan, iteration.aggContext,
								LmdbNativeAttemptMetrics.direct()));
				long usedAfterFailure = manager.usedBytes();
				long createdRuns = NativeSpillSort.SPILL_RUNS.get() - spillsBefore;
				long deletedRuns = NativeSpillSort.DELETED_RUNS.get() - deletedRunsBefore;
				long mergedRuns = NativeSpillSort.MERGED_RUNS.get() - mergedBefore;
				long deletedMergedRuns = NativeSpillSort.DELETED_MERGED_RUNS.get() - deletedMergedBefore;
				assertAll("ordered aggregation preserves the original input failure and releases its spill table",
						() -> assertSame(inputFailure, observed.getCause(),
								"the underlying checked failure remains the reported cause"),
						() -> assertEquals(256, ((RowsThenFailurePlan) input).rowsProduced.get(),
								"the exact admitted prefix reaches the injected terminal input failure"),
						() -> assertEquals(1, cursorCloses.get(), "the failed source cursor closes exactly once"),
						() -> assertTrue(createdRuns > 0L,
								"the failure occurs only after the typed grouping table has spilled input runs"),
						() -> assertEquals(createdRuns + mergedRuns, deletedRuns + deletedMergedRuns,
								"every input and compacted spill run is deleted after failure"),
						() -> assertEquals(baseline, usedAfterFailure,
								"the failed grouping table releases its entire query-ledger reservation"));
			} finally {
				row.closeDecodedInputs();
				iteration.close();
				fixture.source.executionContext().close();
			}
			assertEquals(0L, manager.usedBytes(), "closing the query releases all remaining aggregate ownership");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restoreProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroupLimit);
			restoreProperty(NativeCountGroupStore.ENABLED_PROPERTY, previousGroupsEnabled);
		}
	}

	@Test
	void composedLexicalBoundaryPreservesIndependentPhysicalQuotes(@TempDir Path directory) throws Exception {
		SailRepository repository = repositoryWithSummaryData(directory);
		try {
			String query = "SELECT (SUM(STRLEN(?forwarded)) AS ?total) WHERE { "
					+ "{ SELECT (?cat AS ?renamed) WHERE { { SELECT ?s (GROUP_CONCAT(?v; SEPARATOR=\"|\") AS ?cat) "
					+ "WHERE { ?s <" + PHYSICAL_COST_EX + "value> ?v } GROUP BY ?s } } } "
					+ "BIND(?renamed AS ?forwarded) }";
			List<String> generic = canonical(evaluateRepository(repository, query, false, null));
			Path recordingPath = directory.resolve("composed-lexical-aggregate-openings.jfr");
			List<BindingSet> nativeRows;
			try (Recording recording = new Recording()) {
				recording.enable(AGGREGATE_EVENT).withThreshold(Duration.ZERO);
				recording.start();
				nativeRows = evaluateRepository(repository, query, true,
						LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
				recording.stop();
				recording.dump(recordingPath);
			}
			List<String> nativeResult = canonical(nativeRows);
			List<String> aggregateOpenings = aggregateOpeningEvidence(recordingPath);
			assertEquals(generic, nativeResult, "the lexical alias chain must preserve the generic result");

			GenericPlanNode plan = explainRepository(repository, query,
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			List<String> outerGroups = new ArrayList<>();
			List<String> lexicalGroups = new ArrayList<>();
			collectGroupQuotes(plan, false, outerGroups, lexicalGroups);
			assertEquals(1, outerGroups.size(), "the query has one zero-key outer Group quote");
			assertEquals(1, lexicalGroups.size(), "the lexical subquery has one independently scoped Group quote");
			JsonNode outerQuote = candidate(JsonMapper.builder().build().readTree(outerGroups.get(0)),
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			JsonNode outerQuotes = JsonMapper.builder().build().readTree(outerGroups.get(0));
			JsonNode outerAutoChildQuote = candidate(outerQuotes,
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP + "(autoChild)");
			JsonNode lexicalQuote = candidate(JsonMapper.builder().build().readTree(lexicalGroups.get(0)),
					LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			String physicalEvidence = "optimizedPlan=" + plan
					+ "\nouterGroupCandidateInventory=" + outerGroups.get(0)
					+ "\nlexicalGroupCandidateInventory=" + lexicalGroups.get(0)
					+ "\nactualAggregateOpenings=" + aggregateOpenings
					+ "\naggregateOpeningRecording=" + recordingPath;
			assertAll("composed quotes keep executable typed children beside explicitly unknown alternatives",
					() -> assertNotNull(lexicalQuote, "the admitted lexical child offers nestedLoop"),
					() -> assertTrue(hasFiniteKnownPhysicalQuote(lexicalQuote),
							() -> "the lexical child nestedLoop quote must have finite known totals: " + lexicalQuote
									+ "\n" + physicalEvidence),
					() -> assertNotNull(outerQuote, "the outer aggregate offers nestedLoop"),
					() -> assertTrue(hasFiniteKnownPhysicalQuote(outerQuote),
							() -> "the zero-key outer nestedLoop quote must have finite known totals: " + outerQuote
									+ "\n" + physicalEvidence),
					() -> assertNotNull(outerAutoChildQuote,
							"the independent unbound-AUTO child remains a separate legal inventory entry"),
					() -> assertFalse(outerAutoChildQuote.path("physicalFeaturesKnown").asBoolean(),
							() -> "a child which has not been bound to this lexical input cannot borrow the sibling quote\n"
									+ physicalEvidence),
					() -> assertTrue(outerAutoChildQuote.path("total").isNull(),
							() -> "an independently selected AUTO child remains unknown rather than inheriting typed cost\n"
									+ physicalEvidence));
		} finally {
			repository.shutDown();
		}
	}

	private static List<String> aggregateOpeningEvidence(Path recordingPath) throws IOException {
		return RecordingFile.readAllEvents(recordingPath)
				.stream()
				.filter(event -> AGGREGATE_EVENT.equals(event.getEventType().getName()))
				.map(event -> "evaluationId=" + event.getLong("evaluationId")
						+ ", ownerThreadId=" + event.getLong("ownerThreadId")
						+ ", boundaryId=" + event.getLong("boundaryId")
						+ ", eventThreadId=" + event.getThread().getJavaThreadId()
						+ ", strategy=" + event.getString("strategy")
						+ ", resultDemands=" + event.getString("resultDemands")
						+ ", input=" + event.getString("input")
						+ ", retention=" + event.getString("retention")
						+ ", outcome=" + event.getString("outcome"))
				.toList();
	}

