	@Test
	void streamingResultPayloadLivesUntilTheNextAdvanceOrCursorClose() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(8L << 20, 8L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = numericGroupedFixture()) {
			NativeExecutionContext sourceContext = fixture.source.executionContext();
			LmdbQueryMemoryManager.QueryLedger ledger = sourceContext.memoryLedger();
			long anchor = internExact(fixture.source,
					SimpleValueFactory.getInstance().createLiteral("independent-source-baseline"));
			assertEquals(SimpleValueFactory.getInstance().createLiteral("independent-source-baseline"),
					fixture.source.lazyValue(anchor));
			long sourceBaseline = ledger.usedBytes();
			AggregateSpec[] specs = { AggregateSpec.slot("total", 1, false, AggKind.SUM) };
			NativeGroupIteration iteration = new NativeGroupIteration(fixture.source, fixture.plan, fixture.layout,
					new int[] { 0 }, specs, false, EmptyBindingSet.getInstance(), null, null, false, (TupleExpr) null);
			RowState admission = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
			assertTrue(iteration.initialize(admission), "the ordered numeric rows must be admitted before cursor open");
			NativeGroupResultCursor.GroupingPlan ordered = NativeGroupResultCursor.orderedPlan(iteration, admission);
			assertNotNull(ordered, "the source proves a complete group-prefix order");
			assertTrue(ordered.streaming(), "the admitted complete prefix uses the streaming grouping cursor");
			admission.closeDecodedInputs();

			NativeGroupResultCursor cursor = ordered.open(iteration, sourceContext);
			long firstBytes;
			long secondBytes;
			try {
				NativeResultRow first = cursor.next();
				assertNotNull(first, "the first completed group is published before later groups are consumed");
				assertEquals(100L, Long.parseLong(first.cell("group").value().stringValue()));
				iteration.aggContext.close();
				firstBytes = ledger.usedBytes();
				Literal firstValue = (Literal) first.cell("total").value();
				assertEquals(0, firstValue.decimalValue().compareTo(new BigDecimal("9".repeat(2_048))),
						"the first physical row remains readable after its aggregate cache is retired");
				assertTrue(ledger.usedBytes() > sourceBaseline,
						"the completed physical row owns its exact numeric payload between advances");

				NativeResultRow second = cursor.next();
				assertNotNull(second, "the next ordered group is emitted on the next advance");
				assertEquals(101L, Long.parseLong(second.cell("group").value().stringValue()));
				assertEquals(0, ((Literal) second.cell("total").value()).decimalValue().compareTo(BigDecimal.ONE));
				secondBytes = ledger.usedBytes();
				assertTrue(secondBytes > sourceBaseline,
						"the current physical row remains owned after its own advance");
				assertTrue(secondBytes < firstBytes,
						"advancing releases the previous large result payload and retains only the current small result");
				assertEquals(2, fixture.reads.get(), "both admitted ordered rows are consumed exactly once");
			} finally {
				cursor.close();
				iteration.close();
			}
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"closing the streaming cursor releases its current physical-row payload owner");
			sourceContext.close();
			assertEquals(0L, manager.usedBytes(), "the outer source releases the remaining baseline term");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	private static void assertSpilledReducerPayloads(SyntheticValueSource source, NativeSlotLayout layout,
			AggregateSpec[] specs, LmdbQueryMemoryManager.QueryLedger ledger, long sourceBaseline, long minimumId,
			long maximumId, long sampleId, Literal minimum, Literal maximum, TripleTerm sample,
			boolean boundedFactory) {
		AggContext context = new AggContext(source, true);
		AggState state = boundedFactory
				? AggState.bounded(specs, 0, context, AggregateDistinctChannels.sequential(specs), context.cancellation,
						ledger)
				: AggState.externalMembership(specs, context, context.cancellation, ledger);
		NativeGroupIteration renderer = new NativeGroupIteration(source, EmptyPlan.INSTANCE, layout, new int[0], specs,
				false, EmptyBindingSet.getInstance(), null, null, false, (TupleExpr) null);
		assertTrue(minimumId != NativeLmdbQuerySource.UNKNOWN_ID && maximumId != NativeLmdbQuerySource.UNKNOWN_ID
				&& sampleId != NativeLmdbQuerySource.UNKNOWN_ID,
				"all reducer inputs must have source-owned IDs before accumulation");
		RowState first = aggregateValueRow(source, layout, maximumId, minimumId, sampleId);
		RowState second = aggregateValueRow(source, layout, minimumId, maximumId, sampleId);
		long spillsBefore = NativeBoundedReducerValues.SPILL_FILES_CREATED.get();
		long deletesBefore = NativeBoundedReducerValues.SPILL_FILES_DELETED.get();
		long spillsAfterAccumulation = spillsBefore;
		long deletesAfterClose = deletesBefore;
		try {
			if (boundedFactory) {
				state.add(first);
				state.add(second);
			} else {
				// The external-membership producer has already collapsed each row; these are the exact admitted values.
				state.addExternal(0, maximumId, 1L);
				state.addExternal(1, minimumId, 1L);
				state.addExternal(2, sampleId, 1L);
				state.addExternal(0, minimumId, 1L);
				state.addExternal(1, maximumId, 1L);
				state.addExternal(2, sampleId, 1L);
			}
			first.closeDecodedInputs();
			second.closeDecodedInputs();
			context.close();
			spillsAfterAccumulation = NativeBoundedReducerValues.SPILL_FILES_CREATED.get();
			assertTrue(spillsAfterAccumulation > spillsBefore,
					"large admitted extrema and nested triple payloads must spill under the configured resident limit");
			assertEquals(deletesBefore, NativeBoundedReducerValues.SPILL_FILES_DELETED.get(),
					"the reducer spill remains owned until its state closes");
			assertTrue(ledger.usedBytes() > sourceBaseline,
					"the reducer retains bounded workspace and exact payload ownership after the value cache closes");
			BindingSet actual = renderer.toBindingSet(source, null, state, true);
			Value actualSample = actual.getValue("sample");
			assertTrue(actualSample instanceof TripleTerm, "the nested RDF-star sample must survive codec round-trip");
			TripleTerm actualTriple = (TripleTerm) actualSample;
			assertTrue(actualTriple.getObject() instanceof TripleTerm, "the nested triple level must be preserved");
			Literal actualNestedLiteral = (Literal) ((TripleTerm) actualTriple.getObject()).getObject();
			assertAll("exact reducer spill preserves extrema, RDF-star shape, language, and base direction",
					() -> assertEquals(minimum, actual.getValue("minimum")),
					() -> assertEquals(maximum, actual.getValue("maximum")),
					() -> assertEquals(sample, actualSample),
					() -> assertEquals("ar", actualNestedLiteral.getLanguage().orElse(null)),
					() -> assertEquals(Literal.BaseDirection.RTL, actualNestedLiteral.getBaseDirection()));
		} finally {
			first.closeDecodedInputs();
			second.closeDecodedInputs();
			state.closeExternal();
			context.close();
			renderer.close();
			deletesAfterClose = NativeBoundedReducerValues.SPILL_FILES_DELETED.get();
		}
		assertEquals(spillsAfterAccumulation - spillsBefore, deletesAfterClose - deletesBefore,
				"every bounded payload spill is deleted when its owning reducer closes");
		assertEquals(sourceBaseline, ledger.usedBytes(),
				"closing each reducer restores the live source to its exact pre-accumulation ledger baseline");
	}

	private static void assertWeightedReducerResult(SyntheticValueSource source, NativeSlotLayout layout,
			AggregateSpec[] specs, LmdbQueryMemoryManager.QueryLedger ledger, long sourceBaseline, long firstNumberId,
			long secondNumberId, long firstTextId, long secondTextId, Literal firstNumber, Literal secondNumber,
			Literal firstText, Literal secondText, boolean externalMembership) {
		AggContext context = new AggContext(source, true);
		AggState state = externalMembership
				? AggState.externalMembership(specs, context, context.cancellation, ledger)
				: AggState.bounded(specs, 0, context, AggregateDistinctChannels.sequential(specs), context.cancellation,
						ledger);
		NativeGroupIteration renderer = new NativeGroupIteration(source, EmptyPlan.INSTANCE, layout, new int[0], specs,
				false, EmptyBindingSet.getInstance(), null, null, false, (TupleExpr) null);
		RowState first = aggregateValueRow(source, layout, firstNumberId, firstTextId);
		RowState second = aggregateValueRow(source, layout, secondNumberId, secondTextId);
		try {
			if (externalMembership) {
				addExternalWeightedInput(state, firstNumberId, firstTextId, 3L);
				addExternalWeightedInput(state, secondNumberId, secondTextId, 2L);
			} else {
				state.add(first, 3L);
				state.add(second, 2L);
			}
			first.closeDecodedInputs();
			second.closeDecodedInputs();
			context.close();
			assertTrue(ledger.usedBytes() > sourceBaseline,
					"the weighted reducer owns exact aggregate values after optional input caches close");
			assertTrue(ledger.usedBytes() <= ledger.maxBytes(),
					"weighted result ownership remains bounded by its query ledger");
			BindingSet actual = renderer.toBindingSet(source, null, state, true);
			String expectedAll = String.join("🧩", List.of(firstText.stringValue(), firstText.stringValue(),
					firstText.stringValue(), secondText.stringValue(), secondText.stringValue()));
			String expectedDistinct = String.join("🧩", firstText.stringValue(), secondText.stringValue());
			assertAll(
					"weighted count, numeric reducers, distinct membership, sample, and concatenation preserve the bag",
					() -> assertEquals(BigInteger.valueOf(5L), ((Literal) actual.getValue("count")).integerValue()),
					() -> assertEquals(0, ((Literal) actual.getValue("sum")).decimalValue()
							.compareTo(new BigDecimal("8.75"))),
					() -> assertEquals(0, ((Literal) actual.getValue("avg")).decimalValue()
							.compareTo(new BigDecimal("1.75"))),
					() -> assertEquals(expectedAll, actual.getValue("all").stringValue()),
					() -> assertEquals(expectedDistinct, actual.getValue("distinct").stringValue()),
					() -> assertEquals(BigInteger.valueOf(2L),
							((Literal) actual.getValue("distinctCount")).integerValue()),
					() -> assertEquals(firstText, actual.getValue("sample")));
		} finally {
			first.closeDecodedInputs();
			second.closeDecodedInputs();
			state.closeExternal();
			context.close();
			renderer.close();
		}
		assertEquals(sourceBaseline, ledger.usedBytes(),
				"closing weighted aggregate state restores the source-only ledger baseline");
	}

	private static void addExternalWeightedInput(AggState state, long numberId, long textId, long weight) {
		state.addExternal(0, LmdbNativeAggregateCompiler.NULL_CONTEXT_ID, weight);
		state.addExternal(1, numberId, weight);
		state.addExternal(2, numberId, weight);
		state.addExternal(3, textId, weight);
		// External membership receives one representative per already-deduplicated RDF term.
		state.addExternal(4, textId, 1L);
		state.addExternal(5, textId, 1L);
		state.addExternal(6, textId, 1L);
	}

	private static AggregateSpec[] weightedReducerSpecs() {
		return new AggregateSpec[] {
				AggregateSpec.star("count"),
				AggregateSpec.slot("sum", 0, false, AggKind.SUM),
				AggregateSpec.slot("avg", 0, false, AggKind.AVG),
				AggregateSpec.groupConcat("all", 1, false, "🧩"),
				AggregateSpec.groupConcat("distinct", 1, true, "🧩"),
				AggregateSpec.slot("distinctCount", 1, true, AggKind.COUNT),
				AggregateSpec.slot("sample", 1, false, AggKind.SAMPLE)
		};
	}

	private static void assertPayloadOwnershipForFactory(SyntheticValueSource source, NativeSlotLayout layout,
			AggregateSpec[] specs, LmdbQueryMemoryManager.QueryLedger ledger, long sourceBaseline,
			long firstId, long secondId, long minimumId, long maximumId, BigDecimal expectedSum,
			BigDecimal expectedAverage, Literal minimum, Literal maximum) {
		assertPayloadOwnershipForFactory(source, layout, specs, ledger, sourceBaseline, firstId, secondId, minimumId,
				maximumId, expectedSum, expectedAverage, minimum, maximum, false);
	}

	private static void assertPayloadOwnershipForFactory(SyntheticValueSource source, NativeSlotLayout layout,
			AggregateSpec[] specs, LmdbQueryMemoryManager.QueryLedger ledger, long sourceBaseline,
			long firstId, long secondId, long minimumId, long maximumId, BigDecimal expectedSum,
			BigDecimal expectedAverage, Literal minimum, Literal maximum, boolean externalMembership) {
		AggContext context = new AggContext(source, true);
		AggState state = externalMembership
				? AggState.externalMembership(specs, context, context.cancellation, ledger)
				: AggState.bounded(specs, 0, context, AggregateDistinctChannels.sequential(specs), context.cancellation,
						ledger);
		NativeGroupIteration renderer = new NativeGroupIteration(source, EmptyPlan.INSTANCE, layout, new int[0], specs,
				false, EmptyBindingSet.getInstance(), null, null, false, (TupleExpr) null);
		RowState first = null;
		RowState second = null;
		try {
			if (externalMembership) {
				long[] values = { firstId, firstId, maximumId, minimumId, maximumId };
				for (int index = 0; index < values.length; index++) {
					state.addExternal(index, values[index], 1L);
				}
				long[] nextValues = { secondId, secondId, minimumId, maximumId, minimumId };
				for (int index = 0; index < nextValues.length; index++) {
					state.addExternal(index, nextValues[index], 1L);
				}
			} else {
				first = aggregateValueRow(source, layout, firstId, firstId, maximumId, minimumId, maximumId);
				second = aggregateValueRow(source, layout, secondId, secondId, minimumId, maximumId, minimumId);
				state.add(first);
				state.add(second);
			}
			if (first != null) {
				first.closeDecodedInputs();
				first = null;
			}
			if (second != null) {
				second.closeDecodedInputs();
				second = null;
			}
			context.close();
			assertTrue(ledger.usedBytes() > sourceBaseline,
					"SUM/AVG results and exact MIN/MAX/SAMPLE terms remain charged after the optional value cache closes");
			assertTrue(ledger.usedBytes() <= ledger.maxBytes(), "aggregate payload ownership stays inside its ledger");
			BindingSet actual = renderer.toBindingSet(source, null, state, true);
			assertAll("the owned payloads preserve numeric promotion and exact RDF terms after cache close",
					() -> assertEquals(0, ((Literal) actual.getValue("sum")).decimalValue().compareTo(expectedSum)),
					() -> assertEquals(0, ((Literal) actual.getValue("avg")).decimalValue().compareTo(expectedAverage)),
					() -> assertEquals(minimum, actual.getValue("minimum")),
					() -> assertEquals(maximum, actual.getValue("maximum")),
					() -> assertEquals(maximum, actual.getValue("sample")));
		} finally {
			if (first != null) {
				first.closeDecodedInputs();
			}
			if (second != null) {
				second.closeDecodedInputs();
			}
			state.closeExternal();
			context.close();
			renderer.close();
		}
		assertEquals(sourceBaseline, ledger.usedBytes(),
				"closing the bounded/external reducer releases its value payload without closing the source");
	}

	private static AggregateSpec[] aggregatePayloadSpecs() {
		return new AggregateSpec[] {
				AggregateSpec.slot("sum", 0, false, AggKind.SUM),
				AggregateSpec.slot("avg", 1, false, AggKind.AVG),
				AggregateSpec.slot("minimum", 2, false, AggKind.MIN),
				AggregateSpec.slot("maximum", 3, false, AggKind.MAX),
				AggregateSpec.slot("sample", 4, false, AggKind.SAMPLE)
		};
	}

	private static NativeSlotLayout aggregatePayloadLayout() {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("sum", 0, "avg", 1, "minimum", 2, "maximum", 3,
				"sample", 4), null);
		layout.freeze(List.of("sum", "avg", "minimum", "maximum", "sample"));
		return layout;
	}

	private static RowState aggregateValueRow(SyntheticValueSource source, NativeSlotLayout layout, long... ids) {
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertTrue(NativeRowSeeder.seed(row.slots, layout, row.base, source));
		row.recomputeBoundMask();
		assertEquals(0L, row.boundMask());
		for (int slot = 0; slot < ids.length; slot++) {
			assertTrue(row.bind(slot, ids[slot]), "the seeded aggregate fixture must accept each mapped term ID");
		}
		return row;
	}

	private static long internExact(SyntheticValueSource source, Value value) {
		long id = source.internComputedValue(value);
		assertEquals(value, source.lazyValue(id), "the exact generated term must round-trip through its authority");
		return id;
	}

