	private static void assertPartitionedPrefixStatesAreAccountedBeforeFirstOutput(boolean nullableContext)
			throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
		AtomicLong partialPrefixBytes = new AtomicLong(-1L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = partitionedFixture(partialPrefixBytes, manager, nullableContext)) {
			AggregateSpec[] specs = { AggregateSpec.slot("count", 1, true, AggKind.COUNT) };
			int[] groupSlots = { 0, 3 };
			NativeGroupIteration iteration = new NativeGroupIteration(fixture.source, fixture.plan, fixture.layout,
					groupSlots, specs, false, EmptyBindingSet.getInstance(), null, null, false, null);
			RowState row = new RowState(fixture.source, fixture.layout, EmptyBindingSet.getInstance());
			assertTrue(iteration.initialize(row), "the S-ordered prefix fixture must be admitted before costing");
			NativeAggregateDistinctPlan ordered = LmdbNativeOrderPlanner.aggregate(iteration.arg, groupSlots, specs,
					row);
			assertArrayEquals(new int[] { 0 }, ordered.groupPrefixSlots,
					"the source proves one group-key prefix but leaves the secondary group key within that prefix");
			assertFalse(LmdbNativeOrderPlanner.completeGroupPrefix(ordered, groupSlots));
			long baseline = manager.usedBytes();
			List<BindingSet> results = iteration.evaluatePartitionedOrderedGroups(row, ordered, iteration.aggContext);
			try {
				int expectedGroups = nullableContext ? PARTITIONED_ROWS / 2 + 1 : PARTITIONED_ROWS;
				assertEquals(expectedGroups, results.size());
				assertTrue(partialPrefixBytes.get() >= 0L,
						"the cursor must observe memory after a partial prefix but before the first prefix boundary");
				assertTrue(partialPrefixBytes.get() > baseline,
						"live group states must be bounded/accounted before EOF or the first emitted prefix; bytes="
								+ partialPrefixBytes.get());
				assertTrue(partialPrefixBytes.get() <= manager.perQueryMaxBytes());
				Map<String, Long> actual = new HashMap<>();
				for (BindingSet result : results) {
					String context = result.hasBinding("context") ? result.getValue("context").stringValue()
							: "UNBOUND";
					actual.put(result.getValue("group").stringValue() + "/" + context,
							((Literal) result.getValue("count")).longValue());
				}
				Map<String, Long> expected = new HashMap<>();
				if (nullableContext) {
					expected.put("100/UNBOUND", (long) PARTITIONED_ROWS / 2);
					for (int value = 1; value < PARTITIONED_ROWS; value += 2) {
						expected.put("100/" + (2000 + value), 1L);
					}
				} else {
					for (int value = 0; value < PARTITIONED_ROWS; value++) {
						expected.put("100/" + (2000 + value), 1L);
					}
				}
				assertEquals(expected, actual,
						"all secondary groups, null grouping keys, and exact multiplicities must be retained");
				assertEquals(PARTITIONED_ROWS, fixture.reads.get(), "the exact admitted prefix must be consumed");
			} finally {
				if (results instanceof NativeReplayBindingList replay) {
					replay.close();
				}
				row.closeDecodedInputs();
				iteration.close();
			}
			fixture.source.executionContext().close();
			assertEquals(0L, manager.usedBytes(), "query cleanup releases group state and output replay ownership");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	@Test
	void parallelIrGroupConcatQuoteIncludesItsBoundedEventSortCost(@TempDir Path directory) throws Exception {
		Map<String, String> configuredProperties = Map.ofEntries(
				Map.entry(NATIVE_QUERY_ENGINE_ENABLED, "true"),
				Map.entry("rdf4j.lmdb.janinoCodegen.enabled", "true"),
				Map.entry("rdf4j.lmdb.janinoCodegen.synchronous", "true"),
				Map.entry("rdf4j.lmdb.janinoCodegen.thresholdRows", "0"),
				Map.entry("rdf4j.lmdb.kernelInterpreter.enabled", "true"),
				Map.entry("rdf4j.lmdb.factorizedTail.enabled", "false"),
				Map.entry("rdf4j.lmdb.packedFtree.enabled", "false"),
				Map.entry("rdf4j.lmdb.wcoj.enabled", "false"),
				Map.entry("rdf4j.lmdb.parallel.enabled", "true"),
				Map.entry("rdf4j.lmdb.parallel.threads", "2"),
				Map.entry("rdf4j.lmdb.parallel.maxTasks", "2"),
				Map.entry("rdf4j.lmdb.parallel.minWorkEstimate", "0"),
				Map.entry("rdf4j.lmdb.parallel.startupWork", "0"),
				Map.entry(LmdbNativeParallelKernelAggregate.ENABLED_PROPERTY, "true"));
		Map<String, String> previousProperties = new HashMap<>();
		configuredProperties.forEach((property, value) -> {
			previousProperties.put(property, System.getProperty(property));
			System.setProperty(property, value);
		});
		KernelExecutionTestAccess.resetCostCalibration();
		SailRepository repository = null;
		try {
			repository = repositoryWithSummaryData(directory, true);
			String query = "SELECT ?s (GROUP_CONCAT(?v; SEPARATOR=\"|\") AS ?cat) WHERE { ?s <"
					+ PHYSICAL_COST_EX + "value> ?v } GROUP BY ?s";
			List<String> generic = canonical(evaluateRepository(repository, query, false, null));
			long parallelBefore = LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get();
			List<String> actual = canonical(evaluateRepository(repository, query, true,
					LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL));
			assertEquals(generic, actual,
					"the forced parallel FULL_VALUE route must preserve the exact generic result bag");
			assertTrue(LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get() > parallelBefore,
					"the two-worker fixture must execute the parallel aggregate rather than only offer it");

			GenericPlanNode plan = explainRepository(repository, query,
					LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL);
			List<String> paths = new ArrayList<>();
			collectActualPaths(plan, paths);
			assertTrue(paths.contains(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL),
					() -> "the fixture must actually offer and execute the requested parallel IR route: " + paths
							+ " plan="
							+ plan);
			List<String> metricSets = new ArrayList<>();
			collectAggregateQuotes(plan, metricSets);
			List<JsonNode> parallelQuotes = new ArrayList<>();
			for (String metrics : metricSets) {
				JsonNode quote = candidate(JsonMapper.builder().build().readTree(metrics),
						LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL);
				if (quote != null) {
					parallelQuotes.add(quote);
				}
			}
			assertFalse(parallelQuotes.isEmpty(),
					"the actual parallel FULL_VALUE proposal must be in the legal quote inventory");
			List<Long> workerCounts = new ArrayList<>();
			collectLongMetric(plan, "nativeIrParallelWorkersStartedActual", workerCounts);
			assertTrue(workerCounts.stream().anyMatch(count -> count >= 2L),
					() -> "the explained aggregate must report at least two started workers: " + workerCounts);
			for (JsonNode quote : parallelQuotes) {
				assertTrue(quote.path("physicalFeaturesKnown").asBoolean(),
						() -> "the offered parallel FULL_VALUE event producer must expose its physical quote: "
								+ quote);
				assertTrue(quote.path("total").path("SORT_N_LOG2_N").path("expected").asDouble() > 0D,
						() -> "the event-retaining parallel full result must price its membership/encounter sorting: "
								+ quote);
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
			previousProperties.forEach(NativePhysicalGroupingCostTest::restoreProperty);
		}
	}

	@Test
	void boundedConcatMaterializationAccountsItsUtf16Peak() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = fixture()) {
			AggContext context = new AggContext(fixture.source, true);
			Literal payload = SimpleValueFactory.getInstance().createLiteral("\u03bb\ud83d\ude00");
			long id = fixture.source.internComputedValue(payload);
			AggregateSpec spec = AggregateSpec.groupConcat("text", 1, false, "|");
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			NativeBoundedConcat concat = new NativeBoundedConcat(context, spec, context.cancellation, ledger);
			try {
				int copies = 4096;
				concat.add(id, copies);
				StringBuilder expected = new StringBuilder();
				for (int index = 0; index < copies; index++) {
					if (index != 0) {
						expected.append('|');
					}
					expected.append(payload.getLabel());
				}
				long peakBeforeMaterialize = manager.peakUsedBytes();
				assertEquals(expected.toString(), concat.materialize(),
						"bounded authority references must render the exact ordered Unicode string");
				long peakAfterMaterialize = manager.peakUsedBytes();
				long expectedLiveBuffers = (long) expected.length() * Character.BYTES * 2L;
				assertTrue(peakAfterMaterialize - peakBeforeMaterialize >= expectedLiveBuffers,
						"the simultaneous StringBuilder and immutable String payload must be represented in the query peak; "
								+ "before=" + peakBeforeMaterialize + ", after=" + peakAfterMaterialize + ", chars="
								+ expected.length());
				assertTrue(ledger.usedBytes() <= ledger.maxBytes(), "materialization remains inside the query ledger");
			} finally {
				concat.close();
				context.close();
			}
			fixture.source.executionContext().close();
			assertEquals(0L, manager.usedBytes(), "all materialization and value owners release their charges");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	@Test
	void concatSpillPublishesOnlyCompletePairPagesBeforeMaterialization() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(4L << 20, 4L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		Path temporaryDirectory = Path.of(System.getProperty("java.io.tmpdir"));
		try (Fixture fixture = fixture()) {
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			int pairsPerPage = NativeBoundedConcat.PAIRS;
			int segmentCount = pairsPerPage * 2 + 5;
			long recordBytes = 2L * Long.BYTES;
			long pageBytes = pairsPerPage * recordBytes;
			Set<Path> spillsBefore = Set.copyOf(temporaryFiles(temporaryDirectory, "rdf4j-lmdb-concat-"));
			List<Long> ids = new ArrayList<>(segmentCount);
			List<String> expectedSegments = new ArrayList<>(segmentCount);
			List<Long> expectedWeights = new ArrayList<>(segmentCount);
			for (int index = 1; index <= segmentCount; index++) {
				String segment = "page-" + index + "-λ🧭漢字e\u0301";
				ids.add(internExact(fixture.source, SimpleValueFactory.getInstance().createLiteral(segment)));
				expectedSegments.add(segment);
				expectedWeights.add(index % 3L + 1L);
			}
			long sourceBaseline = ledger.usedBytes();
			AggContext context = new AggContext(fixture.source, true);
			NativeBoundedConcat concat = new NativeBoundedConcat(context,
					AggregateSpec.groupConcat("text", 1, false, "🧩"), context.cancellation, ledger);
			Path spill = null;
			try {
				for (int index = 1; index <= segmentCount; index++) {
					concat.add(ids.get(index - 1), expectedWeights.get(index - 1));

					List<Path> newSpills = temporaryFiles(temporaryDirectory, "rdf4j-lmdb-concat-").stream()
							.filter(path -> !spillsBefore.contains(path))
							.toList();
					if (index <= pairsPerPage) {
						assertTrue(newSpills.isEmpty(),
								"the in-memory first page does not publish a spill before its fixed capacity is exceeded");
						continue;
					}
					assertEquals(1, newSpills.size(), "one concatenation owns one ordered spill file");
					spill = newSpills.get(0);
					long completePages = (index - 1L) / pairsPerPage;
					assertEquals(completePages * pageBytes, Files.size(spill),
							"spill bytes advance only when a complete fixed-size ID/weight page is published; index="
									+ index);
				}

				StringBuilder expected = new StringBuilder();
				boolean hasValue = false;
				for (int index = 0; index < expectedSegments.size(); index++) {
					for (long copy = 0; copy < expectedWeights.get(index); copy++) {
						if (hasValue) {
							expected.append("🧩");
						}
						expected.append(expectedSegments.get(index));
						hasValue = true;
					}
				}
				assertNotNull(spill, "the final partial page is backed by a spill file before materialization");
				assertEquals(pageBytes * ((segmentCount - 1L) / pairsPerPage), Files.size(spill),
						"the last incomplete page remains buffered until the result is requested");
				String firstResult = concat.materialize();
				assertEquals(expected.toString(), firstResult,
						"final page flush preserves weighted Unicode values, order, and separators");
				assertEquals(recordBytes * segmentCount, Files.size(spill),
						"materialization publishes the final partial page exactly once");
				assertEquals(firstResult, concat.materialize(),
						"repeated materialization replays the same complete pages");
				assertEquals(recordBytes * segmentCount, Files.size(spill),
						"repeated materialization does not append duplicate spill records");
			} finally {
				try {
					concat.close();
				} finally {
					context.close();
				}
			}
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"closing the concatenator releases its bounded page owner");
			assertFalse(Files.exists(spill), "closing the concatenator deletes its spill file");
			fixture.source.executionContext().close();
			assertEquals(0L, manager.usedBytes(), "source and page-buffer ownership both return to zero");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	@Test
	void boundedConcatSpillsAndSupportsRepeatedMaterializationAndEarlyClose() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = fixture()) {
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			List<Long> ids = new ArrayList<>();
			List<String> segments = new ArrayList<>();
			for (int index = 0; index < 40; index++) {
				String segment = "λ🧭e\u0301-" + index;
				Literal value = SimpleValueFactory.getInstance().createLiteral(segment);
				long id = fixture.source.internComputedValue(value);
				assertEquals(value, fixture.source.lazyValue(id), "each spill segment must retain its mapped RDF term");
				ids.add(id);
				segments.add(segment);
			}
			long sourceBaseline = ledger.usedBytes();
			AggContext context = new AggContext(fixture.source, true);
			NativeBoundedConcat concat = new NativeBoundedConcat(context,
					AggregateSpec.groupConcat("text", 1, false, "🧩"), context.cancellation, ledger);
			long afterConstruction = ledger.usedBytes();
			try {
				for (long id : ids) {
					concat.add(id, 1L);
				}
				long afterAppend = ledger.usedBytes();
				String expected = String.join("🧩", segments);
				assertEquals(expected, concat.materialize(), "the spill reader must preserve ordered Unicode segments");
				assertEquals(afterAppend, ledger.usedBytes(),
						"temporary materialization bytes are released after rendering");
				assertEquals(expected, concat.materialize(),
						"a retained immutable segment stream can be rendered again");
				assertEquals(afterAppend, ledger.usedBytes(),
						"repeated rendering must not accumulate transient claims");
				assertTrue(afterConstruction > sourceBaseline,
						"the concat owner must charge its bounded resident workspace");
				assertTrue(afterAppend > afterConstruction, "the output spill must retain its bounded owner charge");
			} finally {
				concat.close();
				concat.close();
				context.close();
			}
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"early/idempotent close releases concat and decoder ownership");
			fixture.source.executionContext().close();
			assertEquals(0L, manager.usedBytes(), "the generated terms and spill owners are released at query close");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	@Test
	void boundedConcatAllocationRefusalAndCancellationReleaseSpillOwnership() throws Exception {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(2L << 20, 2L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (Fixture fixture = fixture()) {
			LmdbQueryMemoryManager.QueryLedger ledger = fixture.source.executionContext().memoryLedger();
			List<Long> ids = new ArrayList<>();
			for (int index = 0; index < 40; index++) {
				Literal value = SimpleValueFactory.getInstance()
						.createLiteral("payload-" + index + "-" + "λ🧭".repeat(128));
				ids.add(fixture.source.internComputedValue(value));
			}
			long sourceBaseline = ledger.usedBytes();
			AggregateSpec spec = AggregateSpec.groupConcat("text", 1, false, "🧩");
			AggContext failureContext = new AggContext(fixture.source, true);
			NativeBoundedConcat refused = new NativeBoundedConcat(failureContext, spec, failureContext.cancellation,
					ledger);
			LmdbQueryMemoryManager.Reservation blocker = null;
			try {
				for (long id : ids) {
					refused.add(id, 1L);
				}
				long available = ledger.maxBytes() - ledger.usedBytes();
				assertTrue(available > 1L, "the refusal fixture needs remaining query budget before the blocker");
				blocker = ledger.reserve(available - 1L, null);
				assertNotNull(blocker, "the blocker must leave less than the final Unicode materialization needs");
				assertThrows(
						org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime.AllocationDeniedException.class,
						refused::materialize,
						"materialization must refuse before allocating an unaccounted UTF-16 result");
			} finally {
				if (blocker != null) {
					blocker.close();
				}
				refused.close();
				failureContext.close();
			}
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"failed materialization releases spill and decoder claims");

			AggContext cancelledContext = new AggContext(fixture.source, true);
			NativeBoundedConcat cancelled = new NativeBoundedConcat(cancelledContext, spec,
					cancelledContext.cancellation,
					ledger);
			try {
				for (long id : ids) {
					cancelled.add(id, 1L);
				}
				cancelledContext.cancellation.requestCancellation();
				assertThrows(KernelQueryCancelledException.class, cancelled::materialize,
						"terminal query cancellation must prevent publishing the spilled result");
			} finally {
				cancelled.close();
				cancelled.close();
				cancelledContext.close();
			}
			assertEquals(sourceBaseline, ledger.usedBytes(),
					"cancelled spill cleanup releases every concat reservation");
			fixture.source.executionContext().close();
			assertEquals(0L, manager.usedBytes(), "failed and cancelled generated payload owners are closed");
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
		}
	}

	private static RowState seededEmptyRow(SyntheticValueSource source, NativeSlotLayout layout) {
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertTrue(NativeRowSeeder.seed(row.slots, layout, EmptyBindingSet.getInstance(), source));
		row.recomputeBoundMask();
		assertEquals(0L, row.boundMask());
		assertEquals(LmdbNativeAggregateCompiler.UNKNOWN, row.id(0));
		return row;
	}

	private static boolean containsSuppressed(Throwable failure, Throwable expected) {
		for (Throwable suppressed : failure.getSuppressed()) {
			if (suppressed == expected || containsSuppressed(suppressed, expected)) {
				return true;
			}
		}
		return false;
	}

	private static NativeResultStep singleTermResultStep(Value value) {
		return new NativeResultStep() {
			@Override
			public NativeResultCursor evaluateNative(BindingSet bindings) {
				return new NativeResultCursor() {
					private final NativeCancellationToken cancellation = new NativeCancellationToken();
					private boolean emitted;
					private boolean closed;

					@Override
					public NativeResultRow next() {
						cancellation.check();
						if (closed || emitted) {
							return null;
						}
						emitted = true;
						return new NativeResultRow(new String[] { "opaque" },
								new NativeResultCell[] { NativeResultCell.term(value) });
					}

					@Override
					public NativeCancellationToken cancellation() {
						return cancellation;
					}

					@Override
					public NativeExecutionContext executionContext() {
						return null;
					}

					@Override
					public void close() {
						closed = true;
					}
				};
			}

			@Override
			public CloseableIteration<BindingSet> evaluate(BindingSet bindings) {
				return NativeResultSteps.rdf(evaluateNative(bindings));
			}
		};
	}

	private static final class RecipeSourceStep implements NativeResultStep {
		private final AtomicInteger physicalQuotes;
		private final Value selected;
		private final Value reranked;
		private final boolean rebindable;

		private RecipeSourceStep(AtomicInteger physicalQuotes, Value selected, Value reranked) {
			this(physicalQuotes, selected, reranked, true);
		}

		private RecipeSourceStep(AtomicInteger physicalQuotes, Value selected, Value reranked, boolean rebindable) {
			this.physicalQuotes = physicalQuotes;
			this.selected = selected;
			this.reranked = reranked;
			this.rebindable = rebindable;
		}

		@Override
		public NativeResultCursor evaluateNative(BindingSet bindings) {
			throw new AssertionError("the lexical source is quoted, then its executable child is opened");
		}

		@Override
		public CloseableIteration<BindingSet> evaluate(BindingSet bindings) {
			throw new AssertionError("the lexical source is quoted, then its executable child is opened");
		}

		@Override
		public NativePhysicalResultPlan physicalPlan(BindingSet bindings) {
			Value value = physicalQuotes.incrementAndGet() == 1 ? selected : reranked;
			return rebindable ? immutableSingleTermPlan(value)
					: new NativePhysicalResultPlan(singleTermResultStep(value), SINGLE_TERM_INPUT);
		}
	}

	private static NativePhysicalResultPlan immutableSingleTermPlan(Value value) {
		return new NativePhysicalResultPlan(singleTermResultStep(value), SINGLE_TERM_INPUT,
				(prepared, worker, bindings) -> immutableSingleTermPlan(value));
	}

	private static final class TrackingInvocationSource extends SyntheticValueSource {
		private final AtomicReference<NativeExecutionContext> acquiredContext;
		private final AtomicInteger throwingOwnerCloses;
		private final AtomicInteger laterOwnerCloses;
		private final RuntimeException cleanupFailure;
		private final AtomicBoolean invocationStarted;

		private TrackingInvocationSource(NativeLmdbQuerySource delegate,
				AtomicReference<NativeExecutionContext> acquiredContext,
				AtomicInteger throwingOwnerCloses, AtomicInteger laterOwnerCloses,
				RuntimeException cleanupFailure, AtomicBoolean invocationStarted) {
			super(delegate, PlanValueCatalog.EMPTY);
			this.acquiredContext = acquiredContext;
			this.throwingOwnerCloses = throwingOwnerCloses;
			this.laterOwnerCloses = laterOwnerCloses;
			this.cleanupFailure = cleanupFailure;
			this.invocationStarted = invocationStarted;
		}

		@Override
		SyntheticValueSource forInvocation(NativeGeneratedKeyPlan proof, NativeSlotLayout layout, BindingSet bindings) {
			SyntheticValueSource invocation = super.forInvocation(proof, layout, bindings);
			NativeExecutionContext context = invocation.executionContext();
			acquiredContext.set(context);
			context.nativeState(new Object(), () -> new AutoCloseable() {
				@Override
				public void close() {
					throwingOwnerCloses.incrementAndGet();
					throw cleanupFailure;
				}
			});
			context.nativeState(new Object(), () -> new AutoCloseable() {
				@Override
				public void close() {
					laterOwnerCloses.incrementAndGet();
				}
			});
			invocationStarted.set(true);
			return invocation;
		}
	}

