	private static Fixture orderedConcatFixture(int groups, int rowsPerGroup, boolean actualGroupsGrouped,
			StatementOrder planOrder, String fallbackIndexName, StatementOrder advertisedOrderedRequest,
			boolean floatingValues, Path spillDirectory, Set<String> existingConcatSpills,
			AtomicReference<List<Path>> spillPathsObserved) {
		AtomicInteger reads = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		int totalRows = Math.multiplyExact(groups, rowsPerGroup);
		NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(delegate.idSpace()).thenReturn(delegate);
		when(delegate.hasCanonicalIds()).thenReturn(true);
		when(delegate.idOf(any(Value.class))).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		when(delegate.idOf(any(Value.class), anyInt())).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		when(delegate.lazyValue(anyLong())).thenAnswer(call -> {
			long id = call.getArgument(0);
			if (id >= 200L && id < 200L + totalRows) {
				if (floatingValues) {
					return SimpleValueFactory.getInstance().createLiteral(0.1d + (id - 200L) % 3 * 0.1d);
				}
				return SimpleValueFactory.getInstance().createLiteral("λ🧭e\u0301-" + (id - 200L));
			}
			return SimpleValueFactory.getInstance().createLiteral(Long.toString(id));
		});
		when(delegate.indexName(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn(fallbackIndexName);
		when(delegate.indexName(any(StatementOrder.class), anyLong(), anyLong(), anyLong(), anyLong()))
				.thenAnswer(call -> {
					StatementOrder requested = call.getArgument(0);
					return requested == advertisedOrderedRequest ? fallbackIndexName : "";
				});
		Answer<RecordIterator> records = call -> new RecordIterator() {
			private int position;
			private boolean closed;

			@Override
			public long[] next() {
				if (spillDirectory != null && position >= 33) {
					try {
						List<Path> created = temporaryFiles(spillDirectory, "rdf4j-lmdb-concat-").stream()
								.filter(path -> !existingConcatSpills.contains(path.getFileName().toString()))
								.toList();
						if (!created.isEmpty()) {
							spillPathsObserved.set(created);
						}
					} catch (IOException failure) {
						throw new UncheckedIOException(failure);
					}
				}
				if (position >= totalRows) {
					return null;
				}
				int current = position++;
				reads.incrementAndGet();
				int group = actualGroupsGrouped ? current / rowsPerGroup : current % groups;
				return new long[] { 100L + group, 9L, 200L + current, 0L };
			}

			@Override
			public void close() {
				if (!closed) {
					closed = true;
					closes.incrementAndGet();
				}
			}
		};
		try {
			doAnswer(records).when(delegate)
					.statements(any(StatementOrder.class), anyLong(), anyLong(), anyLong(),
							anyLong());
			doAnswer(records).when(delegate).statements(anyLong(), anyLong(), anyLong(), anyLong());
			doAnswer(records).when(delegate)
					.statementsInEncounterOrder(anyLong(), anyLong(), anyLong(), anyLong(),
							any(NativeLmdbQuerySource.AdjacencyAccessObserver.class));
		} catch (IOException failure) {
			throw new AssertionError("Mockito stubbing must not advance the fixture source", failure);
		}
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(delegate);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("group", 0, "value", 1, "opaque", 2), null);
		layout.freeze(List.of("group", "value", "opaque"));
		PatternPlan plan = new PatternPlan(Term.slot(0), Term.constant(9L), Term.slot(1), Term.constant(0L),
				ContextConstraint.UNRESTRICTED, false, planOrder, fallbackIndexName, totalRows);
		return new Fixture(source, layout, plan, reads, closes);
	}

	private static final class RowsThenFailurePlan implements SlotPlan {
		private final int groupSlot;
		private final int valueSlot;
		private final long valueId;
		private final int successfulRows;
		private final IOException failure;
		private final AtomicInteger cursorCloses;
		private final AtomicInteger rowsProduced = new AtomicInteger();

		private RowsThenFailurePlan(int groupSlot, int valueSlot, long valueId, int successfulRows,
				IOException failure, AtomicInteger cursorCloses) {
			this.groupSlot = groupSlot;
			this.valueSlot = valueSlot;
			this.valueId = valueId;
			this.successfulRows = successfulRows;
			this.failure = failure;
			this.cursorCloses = cursorCloses;
		}

		@Override
		public RowCursor open(RowState row) {
			int entryMark = row.mark();
			return new RowCursor() {
				private boolean closed;

				@Override
				public boolean next() throws IOException {
					row.rollback(entryMark);
					int current = rowsProduced.get();
					if (current == successfulRows) {
						throw failure;
					}
					if (current > successfulRows) {
						return false;
					}
					if (!row.bind(groupSlot, 100L + current % 2L) || !row.bind(valueSlot, valueId)) {
						throw new IllegalStateException("The seeded grouping row must accept each fixture slot");
					}
					rowsProduced.incrementAndGet();
					return true;
				}

				@Override
				public void close() {
					if (!closed) {
						closed = true;
						row.rollback(entryMark);
						cursorCloses.incrementAndGet();
					}
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L << groupSlot | 1L << valueSlot;
		}
	}

