	private static Fixture partitionedFixture(AtomicLong partialPrefixBytes, LmdbQueryMemoryManager manager,
			boolean nullableContext) throws Exception {
		AtomicInteger reads = new AtomicInteger();
		NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(delegate.idSpace()).thenReturn(delegate);
		when(delegate.hasCanonicalIds()).thenReturn(true);
		when(delegate.idOf(any(Value.class))).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		when(delegate.idOf(any(Value.class), anyInt())).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		when(delegate.lazyValue(anyLong()))
				.thenAnswer(call -> SimpleValueFactory.getInstance().createLiteral(Long.toString(call.getArgument(0))));
		when(delegate.lazyValue(anyLong(), anyInt()))
				.thenAnswer(call -> SimpleValueFactory.getInstance().createLiteral(Long.toString(call.getArgument(0))));
		when(delegate.indexName(anyLong(), anyLong(), anyLong(), anyLong())).thenReturn("spoc");
		when(delegate.indexName(any(StatementOrder.class), anyLong(), anyLong(), anyLong(), anyLong()))
				.thenAnswer(call -> call.getArgument(0) == StatementOrder.S ? "spoc" : "");
		Answer<RecordIterator> records = call -> new RecordIterator() {
			private int position;

			@Override
			public long[] next() {
				if (position >= PARTITIONED_ROWS) {
					return null;
				}
				int current = position++;
				reads.incrementAndGet();
				if (current == PARTITIONED_ROWS / 2) {
					partialPrefixBytes.set(manager.usedBytes());
				}
				long context = nullableContext && current % 2 == 0 ? 0L : 2000L + current;
				return new long[] { 100L, 9L, 1000L + current, context };
			}

			@Override
			public void close() {
			}
		};
		doAnswer(records).when(delegate)
				.statements(any(StatementOrder.class), anyLong(), anyLong(), anyLong(), anyLong());
		doAnswer(records).when(delegate).statements(anyLong(), anyLong(), anyLong(), anyLong());
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(delegate);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("group", 0, "value", 1, "opaque", 2, "context", 3), null);
		layout.freeze(List.of("group", "value", "opaque", "context"));
		PatternPlan plan = new PatternPlan(Term.slot(0), Term.constant(9L), Term.slot(1), Term.slot(3),
				ContextConstraint.UNRESTRICTED, false, "spoc", PARTITIONED_ROWS);
		return new Fixture(source, layout, plan, reads);
	}

	private static SailRepository repositoryWithSummaryData(Path directory) {
		return repositoryWithSummaryData(directory, false);
	}

	private static SailRepository repositoryWithSummaryData(Path directory, boolean directAdjacency) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true);
		if (directAdjacency) {
			config.setDirectAdjacencyEnabled(true)
					.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
					.setDirectAdjacencyMaxBytes(1L << 30);
		}
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			var factory = connection.getValueFactory();
			var predicate = factory.createIRI(PHYSICAL_COST_EX, "value");
			connection.begin();
			for (int group = 0; group < SUMMARY_GROUPS; group++) {
				var subject = factory.createIRI(PHYSICAL_COST_EX, "subject-" + group);
				connection.add(subject, predicate, factory.createLiteral("lambda-\u03bb-" + group));
				connection.add(subject, predicate, factory.createLiteral("emoji-\ud83d\ude00-" + group));
				connection.add(subject, predicate, factory.createLiteral("plain-" + group));
			}
			connection.commit();
		}
		return repository;
	}

	private static List<BindingSet> evaluateRepository(SailRepository repository, String query, boolean nativeEnabled,
			String forcedStrategy) {
		String previous = System.getProperty(NATIVE_QUERY_ENGINE_ENABLED);
		System.setProperty(NATIVE_QUERY_ENGINE_ENABLED, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (forcedStrategy != null) {
				prepared.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			try (var rows = prepared.evaluate()) {
				return QueryResults.asList(rows);
			}
		} finally {
			restoreProperty(NATIVE_QUERY_ENGINE_ENABLED, previous);
		}
	}

	private static GenericPlanNode explainRepository(SailRepository repository, String query, String forcedStrategy) {
		String previous = System.getProperty(NATIVE_QUERY_ENGINE_ENABLED);
		System.setProperty(NATIVE_QUERY_ENGINE_ENABLED, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (forcedStrategy != null) {
				prepared.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			return prepared.explain(Explanation.Level.Telemetry).toGenericPlanNode();
		} finally {
			restoreProperty(NATIVE_QUERY_ENGINE_ENABLED, previous);
		}
	}

	private static List<String> canonical(List<BindingSet> rows) {
		List<String> result = new ArrayList<>();
		for (BindingSet row : rows) {
			List<String> bindings = new ArrayList<>();
			for (String name : row.getBindingNames()) {
				bindings.add(name + '=' + row.getValue(name));
			}
			bindings.sort(String::compareTo);
			result.add(String.join("|", bindings));
		}
		result.sort(String::compareTo);
		return result;
	}

	private static void collectAggregateQuotes(GenericPlanNode node, List<String> quotes) {
		String metrics = node.getStringMetricActual(NativeAggregateCostQuotes.METRIC);
		if (metrics != null) {
			quotes.add(metrics);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectAggregateQuotes(child, quotes);
			}
		}
	}

	private static void collectGroupQuotes(GenericPlanNode node, boolean insideNewScope, List<String> outerGroups,
			List<String> lexicalGroups) {
		boolean scoped = insideNewScope || Boolean.TRUE.equals(node.isNewScope());
		if (node.getType() != null && node.getType().startsWith("Group")) {
			String metrics = node.getStringMetricActual(NativeAggregateCostQuotes.METRIC);
			if (metrics != null) {
				(scoped ? lexicalGroups : outerGroups).add(metrics);
			}
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectGroupQuotes(child, scoped, outerGroups, lexicalGroups);
			}
		}
	}

	private static void collectLongMetric(GenericPlanNode node, String metric, List<Long> values) {
		Long value = node.getLongMetricActual(metric);
		if (value != null) {
			values.add(value);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectLongMetric(child, metric, values);
			}
		}
	}

	private static void collectActualPaths(GenericPlanNode node, List<String> paths) {
		String actual = node.getStringMetricActual(LmdbNativeExplain.EXECUTION_PATH);
		if (actual != null) {
			paths.add(actual);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectActualPaths(child, paths);
			}
		}
	}

	private static void restoreProperty(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	private static Map<Path, Long> reducerSpillSizes() throws IOException {
		try (var files = Files.list(Path.of(System.getProperty("java.io.tmpdir")))) {
			Map<Path, Long> sizes = new HashMap<>();
			for (Path path : files.filter(path -> path.getFileName().toString().startsWith("rdf4j-lmdb-reducer-"))
					.toList()) {
				sizes.put(path, Files.size(path));
			}
			return sizes;
		}
	}

